cards.code:
// BROKEN: equals without hashCode
class User {
    String email;
    @Override public boolean equals(Object o) {
        if (!(o instanceof User)) return false;
        return email.equals(((User) o).email);
    }
    // hashCode() inherited from Object -> identity-based
}
// new HashSet<>(); add(u1); add(u2 with same email);
// Both stored because they hash to different buckets

// CORRECT
class User {
    String email;
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        return Objects.equals(email, ((User) o).email);
    }
    @Override public int hashCode() {
        return Objects.hash(email);
    }
}

// MODERN (Java 16+)
record User(String email) {}
// equals and hashCode auto-generated from components

// Lifecycle
NEW --> RUNNABLE --> BLOCKED (waiting for monitor) --> RUNNABLE
              \--> WAITING / TIMED_WAITING --> RUNNABLE
              \--> TERMINATED

// start() vs run() -- the classic trap
Thread t = new Thread(() ->
    System.out.println(Thread.currentThread().getName()));
t.run();    // prints "main" -- runs on caller thread, NO new thread
t.start();  // prints "Thread-0" -- spawns an actual new thread

// Runnable vs Callable
Runnable r = () -> doWork();                    // no return
Callable<Integer> c = () -> computeResult();    // returns Integer

// Daemon thread
Thread bg = new Thread(() -> cleanupLoop());
bg.setDaemon(true); // JVM will not wait for this on exit
bg.start();

// Correct: bounded queue + explicit rejection + named threads
ThreadPoolExecutor pool = new ThreadPoolExecutor(
    10,                                   // corePoolSize
    50,                                   // maximumPoolSize
    60, TimeUnit.SECONDS,                 // keepAliveTime
    new ArrayBlockingQueue<>(1000),       // bounded workQueue
    r -> { Thread t = new Thread(r, "api-worker"); return t; },
    new ThreadPoolExecutor.CallerRunsPolicy()  // backpressure to caller
);

// TRAP: unbounded queue -- maximumPoolSize never triggers
Executors.newFixedThreadPool(10);  // LinkedBlockingQueue with Integer.MAX_VALUE

// Graceful shutdown
pool.shutdown();                          // stop accepting, drain queue
if (!pool.awaitTermination(30, TimeUnit.SECONDS))
    pool.shutdownNow();                   // interrupt + drop queue

// Java 21+ virtual threads (IO-bound workloads)
try (ExecutorService v = Executors.newVirtualThreadPerTaskExecutor()) {
    v.submit(() -> callRemoteService());
}

// Parallel fan-out: user + orders + recommendations
CompletableFuture<User> uF = CompletableFuture.supplyAsync(
    () -> userService.get(id), pool);
CompletableFuture<List<Order>> oF = CompletableFuture.supplyAsync(
    () -> orderService.byUser(id), pool);
CompletableFuture<List<Rec>> rF = CompletableFuture.supplyAsync(
    () -> recService.forUser(id), pool);

CompletableFuture<Page> pageF = uF
    .thenCombine(oF, UserWithOrders::new)
    .thenCombine(rF, Page::new)
    .exceptionally(ex -> Page.fallback(id));   // MUST attach to avoid swallow

Page page = pageF.join();                       // unchecked wait

// Java 9+: deadline
pageF.orTimeout(500, TimeUnit.MILLISECONDS);

// Which thread runs the function?
// thenApply     -> completing thread (unpredictable)
// thenApplyAsync -> pool thread (predictable)

// Comparable: canonical ordering inside the class
class User implements Comparable<User> {
    String name; int age;
    @Override public int compareTo(User o) {
        return Integer.compare(this.age, o.age);   // NOT this.age - o.age
    }
}

// Comparator: external, chainable, reusable
Comparator<User> byAgeThenName = Comparator
    .comparingInt(User::getAge)
    .thenComparing(User::getName)
    .reversed();

users.sort(byAgeThenName);

// Overflow trap
Comparator<Integer> broken = (a, b) -> a - b;   // breaks near Integer.MIN/MAX
Comparator<Integer> fixed  = Integer::compare;

// TreeSet uses compareTo, NOT equals
// class User compareTo -> by email, equals -> by id
// Two users with same email, different ids -> second silently NOT added

// == vs equals
String a = "hello";              // interned in pool
String b = "hello";              // same pooled object
String c = new String("hello");  // fresh heap object, contents equal

a == b;      // true  (same pooled instance)
a == c;      // false (different objects)
a.equals(c); // true  (content comparison)
c.intern() == a;  // true (forced to canonical)

// Loop concat: O(n^2)
String s = "";
for (int i = 0; i < 10_000; i++) s += "x";  // new String every iteration

// Correct
StringBuilder sb = new StringBuilder();
for (int i = 0; i < 10_000; i++) sb.append('x');
String result = sb.toString();

// Password: use char[]
char[] pwd = fetchPassword();
try {
    authenticate(pwd);
} finally {
    Arrays.fill(pwd, '\u0000');   // zero after use
}

// WITHOUT Spring / IoC -- tight coupling
class OrderService {
    private PaymentClient payment = new StripeClient("secret");   // hardcoded
    private OrderRepo repo = new JpaOrderRepo(DataSource.from("jdbc:..."));
    // testing requires editing this file
}

// WITH Spring / DI -- dependencies injected
@Service
class OrderService {
    private final PaymentClient payment;    // interface, not concrete
    private final OrderRepo repo;

    @Autowired
    public OrderService(PaymentClient payment, OrderRepo repo) {
        this.payment = payment;
        this.repo = repo;
    }
}
// container resolves PaymentClient + OrderRepo and wires them in
// tests can pass new FakePaymentClient() directly

Lifecycle chain (in order)

1. Constructor                         <-- instantiation
2. @Autowired field/setter population  <-- dependency injection
3. BeanNameAware / BeanFactoryAware / ApplicationContextAware
4. BeanPostProcessor.postProcessBeforeInitialization  <-- e.g. @PostConstruct discoverers
5. @PostConstruct
6. InitializingBean.afterPropertiesSet
7. @Bean(initMethod = "setup")         <-- custom init
8. BeanPostProcessor.postProcessAfterInitialization   <-- AOP proxies installed here
9. Bean is ready
... usage ...
10. @PreDestroy
11. DisposableBean.destroy
12. @Bean(destroyMethod = "cleanup")   <-- custom destroy

// Scoped proxy -- required for request bean inside singleton
@Component
@Scope(value = "request", proxyMode = ScopedProxyMode.TARGET_CLASS)
class RequestContext { ... }

@Singleton
class ApiService {
    @Autowired RequestContext ctx;  // proxied -- resolves per request
}

cards.summary:
All three annotations are stereotypes — they are functionally @Component with a role hint. If you write @Service on a class, Spring's classpath scanner treats it exactly like @Component and registers a bean. The same is true for @Repository and @Controller. So why do three names exist, and when does the distinction matter? The answer has two parts: documentation (does this class read as a service layer, a data-access layer, or a controller?) and one concrete runtime difference (@Repository adds exception translation).

@Controller marks a web controller. In classic Spring MVC it participates in handler mapping and request routing; in Spring Boot, @RestController is a composed annotation combining @Controller and @ResponseBody. In modern REST applications, @Controller appears only when you need to return view names, and @RestController is more common.

@Service marks a service-layer class — business logic, orchestration, transactions. Spring attaches no extra behavior to @Service; it is purely a semantic hint. Its value is that code readers immediately know 'this class contains business logic' and tools like SonarQube and Spring's own instrumentation use the hint for reporting. It is a label, nothing more.

@Repository has real runtime behavior. Any bean annotated with @Repository gets wrapped by a PersistenceExceptionTranslationPostProcessor bean, which installs an interceptor that catches native persistence exceptions (java.sql.SQLException, JPA PersistenceException, Hibernate JDBCException) and translates them into Spring's unified DataAccessException hierarchy (DuplicateKeyException, DataIntegrityViolationException, CannotAcquireLockException, etc.). Without @Repository, your service layer would need to catch SQLException or a JPA-specific exception, which couples business logic to a specific persistence technology. With @Repository, business code catches Spring exceptions only, and swapping Hibernate for jOOQ or JDBC does not change the catch blocks. In modern Spring Data JPA, @Repository is auto-applied to interface-based repositories (the proxies generated for interfaces extending JpaRepository), so you rarely need to write @Repository by hand — but the exception-translation behavior still applies.

The interview trap is to claim @Service and @Component are functionally different at runtime — they are not. A strong answer explicitly says: 'All three are meta-annotated with @Component, so injection behavior is identical. Only @Repository has additional behavior (exception translation via PersistenceExceptionTranslationPostProcessor). @Controller enables MVC handler mapping when using classic Spring MVC. @Service is purely a semantic marker.' The other trap is to say 'use @Component for utility classes' — utility classes with only static methods should not be beans at all; they are just static utility classes. Use @Component when the class has state or dependencies and is part of the container's dependency graph.

cards.code:
@Component                 // generic bean
class EmailValidator { ... }

@Service                   // semantic only
class OrderService {
    @Autowired PaymentClient payment;
}

@Repository                // ADDS exception translation
class OrderJdbcRepository {
    public Order findById(long id) {
        try {
            return jdbc.query(...);
        } catch (SQLException e) {  // never reached by callers
            throw e;                 // Spring translates to DataAccessException
        }
    }
}

// Caller sees DataAccessException subclasses, not SQLException
@Autowired OrderJdbcRepository repo;
try {
    repo.findById(id);
} catch (DuplicateKeyException e) { ... }  // Spring exception, technology-neutral

// What the annotations actually mean
@Component  = @Component
@Service    = @Component  (semantic hint)
@Repository = @Component  + PersistenceExceptionTranslationPostProcessor applies
@Controller = @Component  + MVC handler mapping

cards.summary:
@Autowired tells the container to inject a dependency. On its own, it is just a marker — the actual resolution algorithm is what determines which bean is chosen, and knowing that algorithm is the difference between 'it works' and 'it fails at startup with NoUniqueBeanDefinitionException'. The default resolution is by type, not by name. This surprises developers coming from XML or Guice, where name-based injection is common.

The algorithm Spring follows for a dependency of type T: (1) find all beans whose type is assignable to T; (2) if exactly one, inject it; (3) if none, throw NoSuchBeanDefinitionException; (4) if multiple, apply @Qualifier on the injection point — a string that must match a bean name or qualifier; (5) if no @Qualifier, check whether one candidate is marked @Primary — if so, inject it; (6) if still ambiguous, fall back to matching the field or parameter name against bean names (this fallback works only if -parameters compiler flag is on, which Spring Boot enables by default); (7) if still ambiguous, throw NoUniqueBeanDefinitionException with a helpful list of candidates. Each step narrows the field; the algorithm stops as soon as exactly one candidate remains.

@Qualifier is the most explicit disambiguation and should be the first tool. @Primary is a declaration on the bean side — useful when one implementation is the 'default' and others are alternatives (e.g., default DataSource). Bean-name fallback is convenient but fragile because it depends on the compiler preserving parameter names; without -parameters, all parameters become arg0, arg1 and the fallback silently fails.

Beyond disambiguation, the injection style matters. Constructor injection (recommended) makes dependencies final, ensures they cannot be null, and fails fast at startup if a required bean is missing. It also makes the class plain-Java testable — a unit test constructs it with new, no Spring context required. Since Spring 4.3, if a class has exactly one constructor, @Autowired on it is optional — Spring uses it automatically. Field injection (@Autowired on a field) is the most compact syntax, but it hides dependencies from the class signature, prevents final fields, and makes the class impossible to instantiate in a plain test without reflection. Setter injection allows optional dependencies and reconfiguration, but lets the bean exist in an incompletely initialized state — dangerous for invariants.

Optional and lazy dependencies have their own annotations. Optional<PaymentClient> makes the dependency optional — if no bean exists, the argument is Optional.empty(). @Autowired(required = false) on a field or setter achieves the same for field injection. @Lazy delays resolution until first use — useful to break cycles or to avoid eagerly loading an expensive bean. ObjectProvider<T> is the modern, container-friendly way to fetch an optional or zero-or-many dependency at use time: provider.getIfAvailable(), provider.getObject(), provider.stream(). It defers resolution out of construction, sidestepping many cycle and startup-ordering issues.

The most common production incidents with @Autowired are: NoUniqueBeanDefinitionException when two beans implement the same interface and no qualifier/primary disambiguates; NullPointerException in tests because field injection never ran (the class was constructed with new and the field was never set); and inconsistent behavior when beans are conditionally registered (@ConditionalOnProperty, @Profile) such that the bean appears in some environments but not others. Constructor injection with explicit qualifiers prevents all three.

cards.code:
// --- By type (default) ---
@Autowired PaymentClient client;
// one bean of type PaymentClient -> injected

// --- Multiple implementations: qualifier ---
@Autowired @Qualifier("stripe") PaymentClient client;

@Bean("stripe")  PaymentClient stripe()  { ... }
@Bean("paypal")  PaymentClient paypal()  { ... }

// --- Or primary ---
@Primary @Bean PaymentClient defaultClient() { ... }

// --- Constructor injection (best) ---
@Service
class OrderService {
    private final PaymentClient client;
    private final OrderRepo repo;

    // @Autowired optional since Spring 4.3 when only one ctor
    public OrderService(PaymentClient client, OrderRepo repo) {
        this.client = client;
        this.repo = repo;
    }
}

// --- Optional / lazy / provider ---
@Autowired Optional<PaymentClient> client;

@Autowired @Lazy ExpensiveClient lazy;   // resolved on first use

@Autowired ObjectProvider<Plugin> plugins;
plugins.stream().forEach(p -> p.run());  // zero or many

// --- Resolution order ---
// type -> @Qualifier -> @Primary -> bean name -> NoUniqueBeanDefinitionException

// BAD: constructor cycle -- fails to start
@Service class A { A(B b) {} }
@Service class B { B(A a) {} }
// BeanCurrentlyInCreationException: Error creating bean 'a'
// Requested bean is currently in creation: Is there an unresolvable circular reference?

// Workaround (do not do this long-term): field injection + @Lazy
@Service class A { @Lazy @Autowired B b; }
@Service class B { @Autowired A a; }

// Three-level cache during field/setter cycle
// 1. Instantiate A (no-arg), put in singletonFactories: factory -> early A (or early proxy)
// 2. Resolve A.b -> needs B
// 3. Instantiate B, populate B.a -> asks for A
//    -> found in singletonFactories -> expose early A (or its proxy) -> earlySingletonObjects
// 4. B completes -> singletonObjects
// 5. A gets B -> completes -> singletonObjects

// Why a third level (singletonFactories) instead of just earlySingletonObjects?
// singletonFactories can decide at exposure time whether to return the raw
// instance or an AOP proxy wrapping it. Without it, cycle + @Transactional
// would silently bypass the proxy and transactions would not apply.

// Spring Boot 2.6+
// spring.main.allow-circular-references=false  (default)

// Correct refactor -- extract shared collaborator
interface Clock { Instant now(); }
@Service class A { A(Clock c) {} }
@Service class B { B(Clock c) {} }
// no cycle, both depend on a leaf

// Three failure modes of Spring AOP

// 1. Final method -- @Transactional silently ignored
@Service
class PaymentService {
    @Transactional
    public final void charge() { ... }   // CGLIB cannot override -> NO txn
}

// 2. Self-invocation -- proxy bypassed
@Service
class OrderService {
    @Transactional
    public void process() {
        validate();                      // this.validate() -- proxy skipped
    }
    @Transactional(propagation = REQUIRES_NEW)
    public void validate() { ... }       // runs in process()'s txn
}
// Fix: move validate() into a separate @Service, or use TransactionTemplate

// 3. Concrete-class injection when bean is a JDK proxy
@Service class UserService implements IUserService { ... }
@Autowired UserService s;                // fails: bean is IUserService proxy
// Fix: inject the interface, or force CGLIB via @EnableAspectJAutoProxy(proxyTargetClass=true)

// How the proxy is chosen
// implements >= 1 interface -> JDK proxy (default in Spring 5)
// no interfaces            -> CGLIB
// proxyTargetClass=true    -> always CGLIB (Spring Boot 2+ default)

// Default -- proxyBeanMethods=true (CGLIB)
@Configuration
class AppConfig {
    @Bean DataSource ds() { return buildPool(); }

    @Bean JdbcTemplate jdbc() {
        return new JdbcTemplate(ds());   // SAME singleton -- proxy intercepts
    }
}

// Lite mode -- proxyBeanMethods=false
@Configuration(proxyBeanMethods = false)
class AppConfig {
    @Bean DataSource ds() { return buildPool(); }

    @Bean JdbcTemplate jdbc() {
        return new JdbcTemplate(ds());   // NEW DataSource -- proxy disabled
    }
}

// Same trap: @Bean inside @Component (never proxied)
@Component
class AppConfig {
    @Bean DataSource ds() { return buildPool(); }
    @Bean JdbcTemplate jdbc() { return new JdbcTemplate(ds()); }   // duplicate
}

// Correct lite-mode pattern -- inject instead of calling
@Configuration(proxyBeanMethods = false)
class AppConfig {
    @Bean DataSource ds() { return buildPool(); }
    @Bean JdbcTemplate jdbc(DataSource ds) { return new JdbcTemplate(ds); }
}

// Verify: enable org.springframework.context DEBUG
// look for 'Enhanced configuration class ...' lines

// Custom BeanFactoryPostProcessor -- modify BeanDefinitions (recipes)
@Component
static class MyBfpp implements BeanFactoryPostProcessor {
    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory bf) {
        BeanDefinition bd = bf.getBeanDefinition("someBean");
        bd.getPropertyValues().add("timeout", 5000);
        // bean itself has not been instantiated yet
    }
}

// Custom BeanPostProcessor -- wrap every bean after init
@Component
static class TimingBpp implements BeanPostProcessor {
    @Override
    public Object postProcessBeforeInitialization(Object bean, String name) {
        return bean;                          // @PostConstruct discoverers run here
    }
    @Override
    public Object postProcessAfterInitialization(Object bean, String name) {
        if (bean instanceof TimedApi) {
            return Proxy.newProxyInstance(   // whatever you return becomes the bean
                bean.getClass().getClassLoader(),
                bean.getClass().getInterfaces(),
                new TimingHandler(bean));
        }
        return bean;
    }
}

// Which BPP installs which feature
@Autowired / @Value    -> AutowiredAnnotationBeanPostProcessor
@PostConstruct         -> CommonAnnotationBeanPostProcessor
@Transactional / AOP   -> AbstractAutoProxyCreator (subclass per feature)
@Repository translation -> PersistenceExceptionTranslationPostProcessor
@Valid                 -> MethodValidationPostProcessor

@SpringBootApplication          // = @SpringBootConfiguration + @EnableAutoConfiguration + @ComponentScan
public class Application {
    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

// What gets auto-configured just by these dependencies in pom.xml
// spring-boot-starter-web        -> Spring MVC + Jackson + embedded Tomcat
// spring-boot-starter-data-jpa   -> Hibernate + HikariCP + transaction manager
// spring-boot-starter-security   -> Spring Security filter chain
// (all wired without any @Configuration class of yours)

// Simplified version of what Boot does internally
@AutoConfiguration
@ConditionalOnClass(DataSource.class)                     // spring-jdbc present
@ConditionalOnMissingBean(DataSource.class)               // user has NOT defined one
@EnableConfigurationProperties(DataSourceProperties.class)
public class DataSourceAutoConfiguration {

    @Configuration
    @ConditionalOnProperty(name = "spring.datasource.url")
    static class PooledDataSourceConfiguration {
        @Bean @ConditionalOnMissingBean
        DataSource dataSource(DataSourceProperties props) {
            return props.initializeDataSourceBuilder()
                        .type(HikariDataSource.class)   // default pool
                        .build();
        }
    }

    @Configuration
    @ConditionalOnMissingBean
    @ConditionalOnClass({ EmbeddedDatabaseType.class })
    static class EmbeddedDataSourceConfiguration {
        @Bean DataSource dataSource() {
            return new EmbeddedDatabaseBuilder().build();   // H2 / HSQLDB
        }
    }
}

// To see what actually happened:
// application.properties
//   logging.level.org.springframework.boot.autoconfigure=DEBUG
// OR
//   java -jar app.jar --debug
//
// Output includes:
//   Positive matches:
//     DataSourceAutoConfiguration.PooledDataSourceConfiguration matched
//   Negative matches:
//     JpaRepositoriesAutoConfiguration#... did not match (no JPA on classpath)

cards.summary:
Both annotations inject values from the Environment into a bean, but they operate at different levels. @Value("${server.port}") injects a single scalar into a single field. @ConfigurationProperties(prefix = "app.payment") binds an entire properties tree to a POJO — every field on the class is populated by looking up app.payment.<field>. The first is a scalpel; the second is a structured mapping.

@Value limitations are well known: no type conversion beyond Spring's basic converters, no relaxed binding (server.port and SERVER_PORT both work but @Value("${server.port}") will not accept server_port as an equivalent, whereas @ConfigurationProperties does), no validation, no IDE auto-completion in application.yml, and no metadata for spring-configuration-metadata.json (the file IDE uses for autocomplete). @Value with SpEL like @Value("#{systemProperties['user.home']}") is powerful but hard to test and fragile — if the property is missing, startup fails with IllegalArgumentException.

@ConfigurationProperties is structured and type-safe. Given a class with fields url, timeout, and apiKey, and prefix app.payment, Boot binds app.payment.url, app.payment.timeout (converted to whatever type timeout has — Duration, int, etc.), and app.payment.api-key (relaxed binding maps kebab-case to camelCase). Nested classes are supported: app.payment.retry.max-attempts binds to a nested Retry.maxAttempts field. Validation works via JSR-380: put @Validated on the class and @NotBlank, @Min on fields — Boot fails startup if a required property is missing or invalid. The @ConfigurationProperties bean can be created as @Bean or registered via @EnableConfigurationProperties, and Boot's metadata generator produces spring-configuration-metadata.json so IDEs autocomplete your properties.

Relaxed binding deserves its own note. With @ConfigurationProperties(prefix = "app.payment"), all of the following bind the same field apiKey: app.payment.api-key (kebab — canonical in yaml), app.payment.apiKey (camel), app.payment.api_key (snake), APP_PAYMENT_API_KEY (env var). @Value("${app.payment.apiKey}") only matches the exact string. In containerized deployments where env vars are the norm, this matters a lot.

When to use each. Use @Value for one-off scalars in a component that has one or two properties — @Value("${app.feature.enabled:false}") with a default is fine. Use @ConfigurationProperties whenever a component has more than two or three related properties, whenever you need validation, whenever you want IDE autocomplete and metadata, and whenever you have nested config. For any real feature that brings its own config (payment, storage, retries, third-party integrations), @ConfigurationProperties is the standard.

One recurring gotcha: @ConfigurationProperties on a class needs to be a Spring bean (annotate with @Component or @ConfigurationPropertiesScan, or register via @EnableConfigurationProperties). Just adding the annotation to a class does not create a bean. The second gotcha: @Value does not validate — if a required value is missing and no default is given, you get a cryptic startup exception; @ConfigurationProperties with @Validated gives you a clear validation error naming the missing field.

cards.code:
// @Value: one-off scalar, no validation, no relaxed binding
@Component
class FeatureFlag {
    @Value("${app.feature.enabled:false}")
    boolean enabled;
}

// @ConfigurationProperties: structured, typed, validated
@ConfigurationProperties(prefix = "app.payment")
@Validated
public class PaymentProperties {
    @NotBlank private String url;
    @Min(1000) private int timeoutMs;
    @NotBlank private String apiKey;
    private Retry retry = new Retry();

    public static class Retry {
        private int maxAttempts = 3;
        private Duration backoff = Duration.ofSeconds(1);
        // getters / setters
    }
    // getters / setters
}

// Register the bean
@SpringBootApplication
@ConfigurationPropertiesScan   // picks up @ConfigurationProperties classes
public class App { ... }

// application.yml (any of these binds to apiKey via relaxed binding)
# app.payment.api-key: sk_test_123
# app.payment.apiKey: sk_test_123
# app.payment.api_key: sk_test_123
# APP_PAYMENT_API_KEY=sk_test_123   (env var)

// Consume
@Service
class PaymentService {
    PaymentService(PaymentProperties props) { ... }
}

// SILENT FAILURE 1: self-invocation
@Service
class OrderService {
    @Transactional public void process() { validate(); }        // proxy bypassed
    @Transactional(propagation = REQUIRES_NEW) public void validate() { ... }
}
// fix: move validate() to another @Service, or use TransactionTemplate

// SILENT FAILURE 2: checked exception commits
@Transactional
public void save() throws IOException {     // throws checked
    repo.save(...);
    if (bad) throw new IOException();       // transaction COMMITS
}
// fix
@Transactional(rollbackFor = Exception.class)

// SILENT FAILURE 3: final method -- CGLIB cannot override
@Transactional public final void lock() { ... }   // no transaction, no warning

// SILENT FAILURE 4: private method -- not proxied
@Transactional private void helper() { ... }     // no transaction

// SILENT FAILURE 5: wrong injection
@Service class Svc implements ISvc { ... }        // bean is ISvc proxy
@Autowired Svc s;                                  // fails at startup
@Autowired ISvc s;                                 // correct

// SILENT FAILURE 6: readOnly on a write
@Transactional(readOnly = true)                    // Hibernate skips flush
public void updateName(Long id) { user.setName("x"); }  // change may not persist

// Imperative alternative -- no proxy, no self-invocation trap
@Service
class OrderService {
    private final TransactionTemplate tx;
    OrderService(PlatformTransactionManager tm) { this.tx = new TransactionTemplate(tm); }

    public void process() {
        tx.execute(status -> { /* work */ return null; });
    }
}

