// BUILDER
public final class HttpClient {
    private final String url;              // required
    private final int timeoutMs;           // required
    private final int retries;             // optional, default 0
    private final boolean retryOn5xx;      // optional, default false
    private final List<Header> headers;    // optional, default empty

    private HttpClient(Builder b) {
        this.url        = b.url;
        this.timeoutMs  = b.timeoutMs;
        this.retries    = b.retries;
        this.retryOn5xx = b.retryOn5xx;
        this.headers    = List.copyOf(b.headers); // defensive copy
    }

    public static Builder builder(String url, int timeoutMs) {
        return new Builder(url, timeoutMs);
    }

    public static final class Builder {
        private final String url;
        private final int timeoutMs;
        private int retries = 0;
        private boolean retryOn5xx = false;
        private final List<Header> headers = new ArrayList<>();

        Builder(String url, int timeoutMs) {
            if (url == null || url.isBlank())
                throw new IllegalArgumentException("url required");
            if (timeoutMs <= 0)
                throw new IllegalArgumentException("timeout must be > 0");
            this.url = url;
            this.timeoutMs = timeoutMs;
        }

        public Builder retries(int n) { this.retries = n; return this; }
        public Builder retryOn5xx(boolean b) { this.retryOn5xx = b; return this; }
        public Builder header(String k, String v) {
            headers.add(new Header(k, v)); return this;
        }

        public HttpClient build() {
            // validate cross-field invariants here, not in setters
            return new HttpClient(this);
        }
    }
}

