// Component interface
interface DataSource {
    String read();
}

// Concrete component
class FileDataSource implements DataSource {
    private final String path;
    FileDataSource(String path) { this.path = path; }
    public String read() { return Files.readString(Path.of(path)); }
}

// Decorators -- same interface, add one behavior each
class BufferedDataSource implements DataSource {
    private final DataSource delegate;
    private final Map<String, String> cache = new HashMap<>();

    BufferedDataSource(DataSource d) { this.delegate = d; }

    public String read() {
        return cache.computeIfAbsent("_", k -> delegate.read());
    }
}

class LoggingDataSource implements DataSource {
    private final DataSource delegate;
    LoggingDataSource(DataSource d) { this.delegate = d; }

    public String read() {
        long start = System.nanoTime();
        try   { return delegate.read(); }
        finally { log.info("read took {}ns", System.nanoTime() - start); }
    }
}

class CompressedDataSource implements DataSource {
    private final DataSource delegate;
    CompressedDataSource(DataSource d) { this.delegate = d; }

    public String read() { return gzip(delegate.read()); }
}

// Stacking decorators -- compose behaviors at runtime
DataSource src = new LoggingDataSource(
                     new BufferedDataSource(
                         new CompressedDataSource(
                             new FileDataSource("data.txt"))));
String content = src.read();

// Order matters:
//   Logging(Buffered(Compressed(x)))   -> logs once, caches compressed output
//   Buffered(Logging(Compressed(x)))   -> logs every read (cache bypassed)

