// Subsystem -- multiple classes with a specific call order
class FileReader      { void open(String p) { ... } }
class AudioDecoder    { Audio decode(FileReader r) { ... } }
class VideoDecoder    { Video decode(FileReader r) { ... } }
class AudioResampler  { Audio resample(Audio a) { ... } }
class AudioEncoder    { Audio encode(Audio a) { ... } }
class VideoEncoder    { Video encode(Video v) { ... } }
class Muxer           { void mux(Audio a, Video v, String out) { ... } }

// WITHOUT facade -- every caller repeats the sequence
class Caller {
    void convert(String in, String out) {
        FileReader r = new FileReader(); r.open(in);
        Audio a = new AudioDecoder().decode(r);
        Video v = new VideoDecoder().decode(r);
        a = new AudioResampler().resample(a);
        a = new AudioEncoder().encode(a);
        v = new VideoEncoder().encode(v);
        new Muxer().mux(a, v, out);
    }
}

// WITH facade -- one clean entry point
class VideoConverterFacade {
    void convert(String in, String out) {
        FileReader r = new FileReader(); r.open(in);
        try {
            Audio a = new AudioEncoder().encode(
                new AudioResampler().resample(
                    new AudioDecoder().decode(r)));
            Video v = new VideoEncoder().encode(
                new VideoDecoder().decode(r));
            new Muxer().mux(a, v, out);
        } finally { r.close(); }
    }
}

// Caller
new VideoConverterFacade().convert("in.mkv", "out.mp4");

