// Component
interface FileSystemNode {
    long size();
    void print(String indent);
}

// Leaf
class FileNode implements FileSystemNode {
    private final String name;
    private final long bytes;
    FileNode(String name, long bytes) { this.name = name; this.bytes = bytes; }
    public long size() { return bytes; }
    public void print(String indent) {
        System.out.println(indent + name + " (" + bytes + "B)");
    }
}

// Composite
class DirectoryNode implements FileSystemNode {
    private final String name;
    private final List<FileSystemNode> children = new CopyOnWriteArrayList<>();
    DirectoryNode(String name) { this.name = name; }

    void add(FileSystemNode node)    { children.add(node); }
    void remove(FileSystemNode node) { children.remove(node); }

    public long size() {
        return children.stream().mapToLong(FileSystemNode::size).sum();
    }

    public void print(String indent) {
        System.out.println(indent + name + "/");
        for (FileSystemNode child : children) child.print(indent + "  ");
    }
}

