// Command interface
interface Command {
    void execute();
    void undo();
}

// Receiver -- the object that does the work
class TextEditor {
    private String content = "";
    void insert(String s, int pos)   { content = content.substring(0,pos) + s + content.substring(pos); }
    void delete(int pos, int len)    { content = content.substring(0,pos) + content.substring(pos+len); }
    String content() { return content; }
}

// Concrete command -- stores enough state to undo itself
class InsertCommand implements Command {
    private final TextEditor editor;
    private final String text;
    private final int pos;
    InsertCommand(TextEditor e, String t, int p) { editor = e; text = t; pos = p; }
    public void execute() { editor.insert(text, pos); }
    public void undo()    { editor.delete(pos, text.length()); }
}

// Invoker -- holds and triggers commands
class UndoStack {
    private final Deque<Command> history = new ArrayDeque<>();
    void run(Command c) { c.execute(); history.push(c); }
    void undo()         { if (!history.isEmpty()) history.pop().undo(); }
}

// Usage
TextEditor editor = new TextEditor();
UndoStack  stack  = new UndoStack();
stack.run(new InsertCommand(editor, "hello", 0));
stack.run(new InsertCommand(editor, " world", 5));
stack.undo();  // content = "hello"

