// Queueing -- commands persisted and replayed
class CommandQueue {
    void enqueue(Command c) { store(c); }       // persist for durability
    void run() {
        Command c = next();
        try { c.execute(); ack(c); }
        catch (Exception e) { nack(c); }        // retry or DLQ
    }
}

// Macro -- a command that runs a list of commands
class MacroCommand implements Command {
    private final List<Command> steps;
    MacroCommand(List<Command> s) { steps = s; }
    public void execute() { steps.forEach(Command::execute); }
    public void undo()    {
        for (int i = steps.size()-1; i >= 0; i--) steps.get(i).undo();
    }
}

