        }
    }

    // Abstract -- subclasses MUST provide
    protected abstract List<Row> parse(byte[] raw);

    // Concrete -- shared implementation
    protected byte[] read(String path) { return Files.readAllBytes(Path.of(path)); }

    protected List<Row> validate(List<Row> rows) {
        return rows.stream().filter(Row::isValid).toList();
    }

    protected int write(List<Row> rows) {
        return repository.saveAll(rows);
    }

    // Hooks -- default no-op, subclasses MAY override
    protected void onSuccess(int count) { }
    protected void onFailure(Exception e) { }
}

class CsvImporter extends DataImporter {
    protected List<Row> parse(byte[] raw) { return parseCsv(raw); }
}

