// State interface
interface OrderState {
    void pay(Order o);
    void ship(Order o);
    void deliver(Order o);
    void cancel(Order o);
    void refund(Order o);
}

// Concrete states -- each knows its legal operations and next states
class PlacedState implements OrderState {
    public void pay(Order o)     { o.charge(); o.setState(new PaidState()); }
    public void ship(Order o)    { throw new IllegalStateException("not paid"); }
    public void deliver(Order o) { throw new IllegalStateException("not shipped"); }
    public void cancel(Order o)  { o.refundIfNeeded(); o.setState(new CancelledState()); }
    public void refund(Order o)  { throw new IllegalStateException("not paid"); }
}

class PaidState implements OrderState {
    public void pay(Order o)     { throw new IllegalStateException("already paid"); }
    public void ship(Order o)    { o.dispatch(); o.setState(new ShippedState()); }
    public void deliver(Order o) { throw new IllegalStateException("not shipped"); }
    public void cancel(Order o)  { o.refund(); o.setState(new CancelledState()); }
    public void refund(Order o)  { o.refund(); o.setState(new RefundedState()); }
}

class ShippedState implements OrderState {
    public void deliver(Order o) { o.markDelivered(); o.setState(new DeliveredState()); }
    public void refund(Order o)  { o.refund(); o.setState(new RefundedState()); }
    // other operations throw
    // ...
}

// Context -- delegates, holds current state
class Order {
    private OrderState state = new PlacedState();
    void setState(OrderState s) { this.state = s; }

    public void pay()     { state.pay(this); }
    public void ship()    { state.ship(this); }
    public void deliver() { state.deliver(this); }
    public void cancel()  { state.cancel(this); }
    public void refund()  { state.refund(this); }
}

// Client
Order o = new Order();
o.pay();       // PlacedState -> PaidState
o.ship();      // PaidState   -> ShippedState
// o.pay()     // ShippedState -> IllegalStateException

// ANTI-PATTERN for comparison -- switch-based
class Order {
    enum State { PLACED, PAID, SHIPPED, DELIVERED, CANCELLED, REFUNDED }
    State s = State.PLACED;

    void pay() {
        switch (s) {
            case PLACED -> { charge(); s = PAID; }
            case PAID, SHIPPED, DELIVERED, CANCELLED, REFUNDED -> throw new IllegalStateException();
        }
    }
    // every new state edits every method -- OCP violation
}

// Handler interface -- one method that may or may not call next
interface RequestHandler {
    void handle(HttpRequest req, HttpResponse res, HandlerChain chain);
}

// Chain -- iterates handlers, each decides to pass or stop
class HandlerChain {
    private final List<RequestHandler> handlers;
    private int index = 0;

    HandlerChain(List<RequestHandler> handlers) { this.handlers = handlers; }

    void proceed(HttpRequest req, HttpResponse res) {
        if (index < handlers.size()) {
            RequestHandler handler = handlers.get(index++);
            handler.handle(req, res, this);   // handler decides to call chain.proceed()
        }
    }
}

// Handlers -- each does its work, then decides
class AuthHandler implements RequestHandler {
    public void handle(HttpRequest req, HttpResponse res, HandlerChain chain) {
        if (!validToken(req)) {
            res.status(401).body("unauthorized");
            return;                            // short-circuit -- do not pass
        }
        chain.proceed(req, res);              // pass to next
    }
}

class RateLimitHandler implements RequestHandler {
    public void handle(HttpRequest req, HttpResponse res, HandlerChain chain) {
        if (!limiter.tryAcquire(req.clientId())) {
            res.status(429).body("rate limited");
            return;                            // short-circuit
        }
        chain.proceed(req, res);
    }
}

class ValidationHandler implements RequestHandler {
    public void handle(HttpRequest req, HttpResponse res, HandlerChain chain) {
        if (!valid(req.body())) {
            res.status(400).body("invalid");
            return;
        }
        chain.proceed(req, res);
    }
}

class BusinessHandler implements RequestHandler {
    public void handle(HttpRequest req, HttpResponse res, HandlerChain chain) {
        res.status(200).body(service.execute(req.body()));
        // terminal -- no chain.proceed()
    }
}

// Assemble
HandlerChain chain = new HandlerChain(List.of(
    new AuthHandler(),
    new RateLimitHandler(),
    new ValidationHandler(),
    new BusinessHandler()));
chain.proceed(req, res);

