// Element hierarchy -- stable
interface Expr {
    <R> R accept(Visitor<R> v);
}
class Number implements Expr {
    final int value;
    Number(int v) { value = v; }
    public <R> R accept(Visitor<R> v) { return v.visitNumber(this); }
}
class Add implements Expr {
    final Expr left, right;
    Add(Expr l, Expr r) { left = l; right = r; }
    public <R> R accept(Visitor<R> v) { return v.visitAdd(this); }
}
class Mul implements Expr {
    final Expr left, right;
    Mul(Expr l, Expr r) { left = l; right = r; }
    public <R> R accept(Visitor<R> v) { return v.visitMul(this); }
}

// Visitor interface -- one method per element type
interface Visitor<R> {
    R visitNumber(Number n);
    R visitAdd(Add a);
    R visitMul(Mul m);
}

// Operation 1: evaluate
class EvalVisitor implements Visitor<Integer> {
    public Integer visitNumber(Number n) { return n.value; }
    public Integer visitAdd(Add a)        { return a.left.accept(this) + a.right.accept(this); }
    public Integer visitMul(Mul m)        { return m.left.accept(this) * m.right.accept(this); }
}

// Operation 2: pretty-print
class PrintVisitor implements Visitor<String> {
    public String visitNumber(Number n) { return String.valueOf(n.value); }
    public String visitAdd(Add a)        { return "(" + a.left.accept(this) + " + " + a.right.accept(this) + ")"; }
    public String visitMul(Mul m)        { return "(" + m.left.accept(this) + " * " + m.right.accept(this) + ")"; }
}

// Usage
Expr e = new Add(new Number(1), new Mul(new Number(2), new Number(3)));
e.accept(new EvalVisitor());   // 7
e.accept(new PrintVisitor());  // "(1 + (2 * 3))"

// Adding a new operation -- one new class, no element edits
class DepthVisitor implements Visitor<Integer> {
    public Integer visitNumber(Number n) { return 1; }
    public Integer visitAdd(Add a)        { return 1 + Math.max(a.left.accept(this), a.right.accept(this)); }
    public Integer visitMul(Mul m)        { return 1 + Math.max(m.left.accept(this), m.right.accept(this)); }
}

// Adding a new element type -- painful
// class Sub implements Expr { ... }
// every existing Visitor must now implement visitSub()

// Modern alternative: sealed + pattern matching
sealed interface Expr permits Number, Add, Mul { }
static int eval(Expr e) {
    return switch (e) {
        case Number n -> n.value();
        case Add a    -> eval(a.left()) + eval(a.right());
        case Mul m    -> eval(m.left()) * eval(m.right());
    };
}
// exhaustiveness enforced by the compiler; no accept() ceremony

// ===== MEMENTO =====

// Memento -- opaque snapshot, only the originator knows how to read it
final class EditorMemento {
    private final String content;
    private final int cursor;
    private EditorMemento(String c, int cur) { content = c; cursor = cur; }
    // no public getters -- caretaker must not inspect
}

// Originator -- creates and restores its own mementos
class Editor {
    private String content = "";
    private int cursor = 0;

    void insert(String s) { content = content.substring(0, cursor) + s + content.substring(cursor); cursor += s.length(); }

    EditorMemento save()    { return new EditorMemento(content, cursor); }
    void restore(EditorMemento m) { content = m.content; cursor = m.cursor; }
}

// Caretaker -- stores mementos, never inspects
class UndoStack {
    private final Deque<EditorMemento> stack = new ArrayDeque<>();
    void push(EditorMemento m) { stack.push(m); }
    EditorMemento pop()        { return stack.pop(); }
}

// Usage
Editor ed = new Editor();
UndoStack undo = new UndoStack();
undo.push(ed.save());
ed.insert("hello");
undo.push(ed.save());
ed.insert(" world");
ed.restore(undo.pop());   // content = "hello"

// ===== MEDIATOR =====

// Colleagues -- they never reference each other, only the mediator
interface Colleague { void receive(String from, String msg); String name(); }

// Mediator
class ChatRoom {
    private final Map<String, Colleague> members = new ConcurrentHashMap<>();

    void join(Colleague c)  { members.put(c.name(), c); }
    void leave(Colleague c) { members.remove(c.name()); }

    void send(String from, String msg) {
        for (Colleague c : members.values()) {
            if (!c.name().equals(from)) c.receive(from, msg);
        }
    }
}

class User implements Colleague {
    private final String name;
    private final ChatRoom room;
    User(String n, ChatRoom r) { name = n; room = r; }
    public String name() { return name; }
    public void receive(String from, String msg) { System.out.println(name + " <- " + from + ": " + msg); }
    void say(String msg)  { room.send(name, msg); }   // only knows the mediator
}

// Usage
ChatRoom room = new ChatRoom();
User alice = new User("alice", room);
User bob   = new User("bob",   room);
room.join(alice); room.join(bob);
alice.say("hi");    // bob receives it, alice does not

